<script setup lang="ts">
import type { RouteTemplate, Station, CommandResult, Page } from '~/utils/types'
const api=useApi();const templates=ref<RouteTemplate[]>([]);const stations=ref<Station[]>([]);const error=ref<unknown>();const loading=ref(true);const saving=ref(false);const message=ref('')
const form=reactive({title:'',document_number:'',template:''});const selected=computed(()=>templates.value.find(t=>`${t.id}:${t.version}`===form.template));const valid=computed(()=>Boolean(form.title.trim()||form.document_number.trim()))
function label(id:string){return stations.value.find(s=>s.id===id)?.name||id}
onMounted(async()=>{try{const values=await Promise.all([api.get<RouteTemplate[]>('/route-templates'),api.get<Page<Station>>('/stations')]);templates.value=values[0];stations.value=values[1].items}catch(e){error.value=e}finally{loading.value=false}})
async function save(){if(!valid.value||!selected.value)return;saving.value=true;error.value=undefined;try{const result=await api.command<CommandResult>('/documents',{title:form.title.trim()||null,document_number:form.document_number.trim()||null,origin_station_id:selected.value.station_ids[0],template_id:selected.value.id,template_version:selected.value.version});message.value='บันทึกหนังสือแล้ว';if(result.document_ids[0])await navigateTo(`/documents/${result.document_ids[0]}`)}catch(e){error.value=e}finally{saving.value=false}}
</script>
<template><div class="page-head"><div><h1>ลงทะเบียนหนังสือ</h1><p>เลือก Route Template และกรอกเลขหนังสือหรือชื่อเรื่องอย่างน้อยหนึ่งอย่าง</p></div></div><Feedback :error="error" :message="message" /><UProgress v-if="loading" /><form v-else class="panel" @submit.prevent="save"><div class="form-grid"><div class="field"><label for="document-number">เลขหนังสือ</label><input id="document-number" data-testid="document-number" v-model="form.document_number" maxlength="255" :required="!form.title.trim()" /></div><div class="field"><label for="document-title">ชื่อเรื่อง</label><input id="document-title" data-testid="document-title" v-model="form.title" maxlength="500" :required="!form.document_number.trim()" /></div></div><div class="field"><label for="document-template">เส้นทางและเวอร์ชัน</label><select id="document-template" data-testid="document-template" v-model="form.template" required><option disabled value="">เลือก Route Template</option><option v-for="t in templates" :key="`${t.id}:${t.version}`" :value="`${t.id}:${t.version}`">{{t.name}} · เวอร์ชัน {{t.version}}</option></select></div><div v-if="!templates.length" class="notice">ยังไม่มีเส้นทางที่คุณมีสิทธิ์ต้นทาง กรุณา <NuxtLink class="text-link" to="/templates">สร้าง Route Template</NuxtLink> หรือติดต่อผู้ดูแลหน่วยงาน</div><ol v-if="selected" class="route-steps"><li v-for="(id,i) in selected.station_ids" :key="i"><small>จุดที่ {{i+1}}</small>{{label(id)}}</li></ol><p class="hint">เมื่อบันทึกสำเร็จ ระบบเลือกและตรึง Model A/B พร้อม policy ตามค่าเริ่มต้นของส่วนกลาง ณ ขณะสร้าง ไม่สามารถเลือก Model รายหนังสือได้ การเปลี่ยนค่าเริ่มต้นหรือ Template ภายหลังไม่เปลี่ยนหนังสือเดิม</p><div class="actions"><button data-testid="document-register" class="button primary" :disabled="saving||!valid||!selected">{{saving?'กำลังลงทะเบียน…':'ลงทะเบียนหนังสือ'}}</button><NuxtLink class="button" to="/documents">กลับทะเบียน</NuxtLink></div></form></template>
